{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 길고양이 중성화 사업에서 고양이를 데려가서 하는 일과 번식 방지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제22조제2항에 따르면, 시장 또는 구청장은 길고양이를 중성화의 목적으로 포획한 경우에는 중성화하여 포획장소에 방사해야 합니다. 따라서 이 사업은 길고양이를 포획한 뒤 중성화 수술을 하여 번식하지 못하게 하는 것이 목적입니다. 다만 길고양이의 안전과 보호를 위해 필요한 경우에는 다른 장소를 정하여 방사할 수 있습니다.",
          "b_ids": "동물보호:제22조제2항, 동물보호:제22조제2항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
